import {
    Table,
    BooleanColumn,
    GenericColumn,
    TableNameColumn,
    FieldNameColumn,
    StringColumn,
    TranslatedTextColumn,
} from '../../db'

export const sys_relationship = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Relationship',
    name: 'sys_relationship',
    schema: {
        advanced: BooleanColumn({
            default: false,
            label: 'Advanced',
        }),
        apply_to: GenericColumn({
            columnType: 'script_plain',
            label: [
                {
                    hint: 'Return true if this list applies to provided table',
                    label: 'Apply to',
                    plural: 'Apply to',
                },
            ],
            maxLength: 4000,
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        insert_callback: GenericColumn({
            columnType: 'script_plain',
            label: [
                {
                    hint: 'After an insert made through this relationship, run this script',
                    label: 'Insert callback',
                    plural: 'Insert callbacks',
                },
            ],
            maxLength: 4000,
        }),
        basic_query_from: TableNameColumn({
            attributes: {
                allow_public: true,
            },
            label: 'Queries from table',
        }),
        reference_field: FieldNameColumn({
            attributes: {
                types: 'reference',
            },
            dependent: 'basic_query_from',
            label: 'Reference field',
        }),
        related_list: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Related list',
            maxLength: 32,
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),
        name: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Name',
        }),
        query_with: GenericColumn({
            columnType: 'script_plain',
            default: `(function refineQuery(current, parent) {

	// Add your code here, such as current.addQuery(field, value);

})(current, parent);`,
            label: [
                {
                    hint: 'Add conditions to current',
                    label: 'Query with',
                    plural: 'Query with',
                },
            ],
            maxLength: 4000,
        }),
        basic_apply_to: TableNameColumn({
            attributes: {
                allow_public: true,
            },
            label: 'Applies to table',
        }),
        query_from: GenericColumn({
            columnType: 'script_plain',
            label: [
                {
                    hint: 'Set answer to tablename to query from',
                    label: 'Query from',
                    plural: 'Query froms',
                },
            ],
            maxLength: 4000,
        }),
        simple_reference: BooleanColumn({
            label: 'Simple reference',
        }),
    },
    textIndex: true,
})
